#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <stdio.h>
#include <wchar.h>
int wmain(int argc, wchar_t **argv) { STARTUPINFOW si={sizeof(si)};PROCESS_INFORMATION pi={0};WCHAR cmd[MAX_PATH*2]; ULONG_PTR target=0;DWORD hits=0,exitcode=259;BOOL done=FALSE,initial=FALSE,wxinitial=FALSE; ULONGLONG end;if(argc!=2)return 87;swprintf_s(cmd,MAX_PATH*2,L"\"%ls\"",argv[1]);if(!CreateProcessW(argv[1],cmd,0,0,FALSE,DEBUG_PROCESS|CREATE_NO_WINDOW,0,0,&si,&pi))return 2;DebugSetProcessKillOnExit(FALSE);end=GetTickCount64()+15000;
while(!done&&GetTickCount64()<end){DEBUG_EVENT e;DWORD how=DBG_CONTINUE;if(!WaitForDebugEvent(&e,100)){if(GetLastError()==ERROR_SEM_TIMEOUT)continue;break;}if(e.dwDebugEventCode==CREATE_PROCESS_DEBUG_EVENT){target=(ULONG_PTR)e.u.CreateProcessInfo.lpBaseOfImage+0x1010u;printf("BASE=%p TARGET=%p\n",e.u.CreateProcessInfo.lpBaseOfImage,(void*)target);if(e.u.CreateProcessInfo.hFile)CloseHandle(e.u.CreateProcessInfo.hFile);CloseHandle(e.u.CreateProcessInfo.hThread);CloseHandle(e.u.CreateProcessInfo.hProcess);} else if(e.dwDebugEventCode==CREATE_THREAD_DEBUG_EVENT)CloseHandle(e.u.CreateThread.hThread);else if(e.dwDebugEventCode==LOAD_DLL_DEBUG_EVENT){if(e.u.LoadDll.hFile)CloseHandle(e.u.LoadDll.hFile);}else if(e.dwDebugEventCode==EXCEPTION_DEBUG_EVENT){DWORD code=e.u.Exception.ExceptionRecord.ExceptionCode;ULONG_PTR addr=(ULONG_PTR)e.u.Exception.ExceptionRecord.ExceptionAddress;printf("EXCEPTION code=%08lx addr=%p first=%lu\n",code,(void*)addr,e.u.Exception.dwFirstChance);if((code==EXCEPTION_BREAKPOINT||code==0x4000001fu)&&addr==target){hits++;printf("TARGET_HIT exact=1\n");}else if(code==EXCEPTION_BREAKPOINT&&!initial)initial=TRUE;else if(code==0x4000001fu&&!wxinitial)wxinitial=TRUE;else how=DBG_EXCEPTION_NOT_HANDLED;}else if(e.dwDebugEventCode==EXIT_PROCESS_DEBUG_EVENT){exitcode=e.u.ExitProcess.dwExitCode;done=TRUE;}if(!ContinueDebugEvent(e.dwProcessId,e.dwThreadId,how))break;}
printf("CALIBRATION done=%u exit=%lu hits=%lu\n",done,exitcode,hits);if(!done)DebugActiveProcessStop(pi.dwProcessId);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return done&&exitcode==0&&hits==1?0:1;}
